// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.diimport android.content.Contextimport com.roshan.persona.di.AppInitializerimport com.roshan.persona.di.Priorityimport com.roshan.persona.voice.speaker.SpeakerRecognitionEngineimport com.roshan.persona.voice.speaker.VoicePrintStoreimport com.roshan.persona.voice.wakeword.SpeakerPreCheckBridgeimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.SupervisorJobimport kotlinx.coroutines.launchimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Voice Initializer (Module 5 v2 — audit P0). * * Wires the [SpeakerPreCheckBridge] at app boot so that wake-word detection * can use real speaker recognition instead of the hardcoded `return true`. * * Also loads enrolled voice prints into the bridge so owner-only mode works * from the first wake word (not just after the first recognition call). */@Singletonclass VoiceInitializer @Inject constructor(    private val speakerRecognitionEngine: SpeakerRecognitionEngine,    private val voicePrintStore: VoicePrintStore,) : AppInitializer {    override val priority: Priority = Priority.NORMAL    override val isBlocking: Boolean = false    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)    override fun initialize(context: Context) {        // Wire the SpeakerPreCheckBridge so SpeakerPreCheck.matchesOwner() can        // delegate to the real SpeakerRecognitionEngine.        SpeakerPreCheckBridge.speakerRecognitionEngine = speakerRecognitionEngine        // Load enrolled voice prints async (don't block app boot).        scope.launch {            try {                val prints = voicePrintStore.loadAll()                SpeakerPreCheckBridge.ownerVoicePrints = prints                Timber.tag("NOUS.Voice").i("VoiceInitializer: loaded ${prints.size} voice print(s) into SpeakerPreCheckBridge.")            } catch (t: Throwable) {                Timber.tag("NOUS.Voice").e(t, "VoiceInitializer: failed to load voice prints — speaker pre-check will allow all (no enrollment).")            }        }    }}